/* ===== AMBIENT BACKGROUND ===== */
.ambient-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  background: linear-gradient(-45deg, #faf9f7, #e8e4e0, #d6d2cd, #c8c4bf);
  background-size: 400% 400%;
  animation: ambientShift 20s ease infinite;
  transition: background 0.6s ease;
}

body.dark-mode .ambient-bg {
  background: linear-gradient(-45deg, #1a1a1a, #2a2a2a, #1e1e1e, #252525);
  background-size: 400% 400%;
  animation: ambientShift 25s ease infinite;
}

@keyframes ambientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* ===== CURSOR TRAIL ===== */
.cursor-trail {
  position: fixed;
  pointer-events: none;
  z-index: 9999;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(0, 122, 204, 0.3);
  transform: translate(-50%, -50%);
  transition: width 0.2s, height 0.2s, opacity 0.2s;
}

body.dark-mode .cursor-trail {
  background: rgba(0, 122, 204, 0.5);
}

/* ===== LAYOUT ===== */
.lookbook-container {
  max-width: 1400px;
  margin: 2rem auto;
  padding: 0 1.5rem;
  position: relative;
  z-index: 1;
}

/* ===== SPREADS ===== */
.ship-spread {
  display: none;
  gap: 2rem;
  align-items: stretch;
  margin: 1rem 0;
  animation: fadeIn 0.5s ease;
}

.ship-spread.active {
  display: grid !important;
  grid-template-columns: 1fr 1fr !important;
  gap: 2rem !important;
  width: 100% !important;
}

.ship-spread.intro.active {
  display: block !important;
}

.ship-spread.toc.active {
  display: block !important;
}

.ship-spread .page {
  width: 100% !important;
  min-height: 300px !important;
  padding: 1.75rem;
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.05);
  display: flex;
  flex-direction: column;
  justify-content: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  position: relative;
}

.ship-spread .page:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(0,0,0,0.08);
}

.ship-spread .page h3 {
